import flask
from flask import Flask, request, jsonify, g
import subprocess
import os
import re
import hashlib
import hmac

app = Flask(__name__)

# Configuration
ALLOWED_COMMANDS = ['status', 'health', 'version', 'uptime']
SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')
DEPLOY_DIR = os.environ.get('DEPLOY_DIR', '/opt/app/deploy')

def verify_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    if not signature:
        return False
    expected = 'sha256=' + hmac.new(
        SECRET_KEY.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.before_request
def set_request_context():
    g.request_id = request.headers.get('X-Request-ID', 'unknown')
    g.source_ip = request.headers.get('X-Forwarded-For', request.remote_addr)

@app.route('/api/v1/system/<command>', methods=['GET'])
def system_command(command):
    """Execute allowed system commands for monitoring"""
    if command not in ALLOWED_COMMANDS:
        return jsonify({'error': 'command not permitted'}), 403

    try:
        result = subprocess.run(
            ['systemctl', command],
            capture_output=True, text=True, timeout=10
        )
        return jsonify({'output': result.stdout, 'rc': result.returncode})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'timeout'}), 504

@app.route('/api/v1/deploy/webhook', methods=['POST'])
def deploy_webhook():
    """Handle deployment webhook from CI/CD pipeline"""
    payload = request.get_data()
    signature = request.headers.get('X-Hub-Signature-256')

    if not verify_signature(payload, signature):
        return jsonify({'error': 'invalid signature'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid payload'}), 400

    ref = data.get('ref', '')
    repo = data.get('repository', {}).get('full_name', '')

    # Validate ref format
    if not re.match(r'^refs/(heads|tags)/[a-zA-Z0-9._/-]+$', ref):
        return jsonify({'error': 'invalid ref'}), 400

    branch = ref.split('/', 2)[2]

    # Execute deployment script with branch parameter
    deploy_script = os.path.join(DEPLOY_DIR, 'run.sh')
    cmd = f"{deploy_script} --branch {branch} --repo {repo}"

    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True,
            timeout=120, cwd=DEPLOY_DIR
        )
        return jsonify({
            'status': 'deployed' if result.returncode == 0 else 'failed',
            'output': result.stdout[-500:],
            'branch': branch
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deploy timeout'}), 504

@app.route('/api/v1/config/reload', methods=['POST'])
def reload_config():
    """Reload application configuration from disk"""
    auth = request.headers.get('Authorization')
    if auth != f'Bearer {SECRET_KEY}':
        return jsonify({'error': 'unauthorized'}), 401

    config_path = request.json.get('path', '/etc/app/config.yaml')
    # Prevent directory traversal
    if '..' in config_path or not config_path.startswith('/etc/app/'):
        return jsonify({'error': 'invalid path'}), 400

    try:
        with open(config_path, 'r') as f:
            content = f.read()
        return jsonify({'status': 'loaded', 'size': len(content)})
    except FileNotFoundError:
        return jsonify({'error': 'not found'}), 404

@app.route('/healthz')
def healthz():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
